tool_use_result.content:
/* CreativeHub Design System */
@import url('https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800&display=swap');

:root {
  /* Brand Colors */
  --brand-primary: #F02D00;
  --brand-primary-dark: #D02800;
  --brand-primary-light: #FF4D2E;
  --foreground: #171717;
  --white: #FFFFFF;
  --bg-surface: #FAFAFA;
  --bg-elevated: #FFFFFF;
  --bg-muted: #F5F5F5;

  /* OKLCH Conversions for reference */
  /* --brand-primary: oklch(55% 0.22 25); */
  /* --foreground: oklch(10% 0.01 265); */

  /* Typography */
  --font-family: 'Inter', -apple-system, BlinkMacSystemFont, sans-serif;
  --font-size-xs: 0.75rem;
  --font-size-sm: 0.875rem;
  --font-size-base: 1rem;
  --font-size-lg: 1.125rem;
  --font-size-xl: 1.25rem;
  --font-size-2xl: 1.5rem;
  --font-size-3xl: 1.875rem;
  --font-size-4xl: 2.25rem;
  --font-size-5xl: 3rem;
  --font-size-6xl: 3.75rem;

  /* Spacing */
  --space-1: 0.25rem;
  --space-2: 0.5rem;
  --space-3: 0.75rem;
  --space-4: 1rem;
  --space-5: 1.25rem;
  --space-6: 1.5rem;
  --space-8: 2rem;
  --space-10: 2.5rem;
  --space-12: 3rem;
  --space-16: 4rem;
  --space-20: 5rem;
  --space-24: 6rem;

  /* Border Radius */
  --radius-sm: 0.25rem;
  --radius-md: 0.5rem;
  --radius-lg: 0.75rem;
  --radius-xl: 1rem;
  --radius-2xl: 1.5rem;
  --radius-full: 9999px;

  /* Shadows */
  --shadow-sm: 0 1px 2px rgba(0,0,0,0.05);
  --shadow-md: 0 4px 6px -1px rgba(0,0,0,0.1), 0 2px 4px -2px rgba(0,0,0,0.1);
  --shadow-lg: 0 10px 15px -3px rgba(0,0,0,0.1), 0 4px 6px -4px rgba(0,0,0,0.1);
  --shadow-xl: 0 20px 25px -5px rgba(0,0,0,0.1), 0 8px 10px -6px rgba(0,0,0,0.1);

  /* Transitions */
  --transition-fast: 150ms ease;
  --transition-base: 200ms ease;
  --transition-slow: 300ms ease;
}

/* Reset & Base */
*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html {
  font-size: 16px;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

body {
  font-family: var(--font-family);
  font-size: var(--font-size-base);
  line-height: 1.6;
  color: var(--foreground);
  background-color: var(--white);
}

a {
  color: inherit;
  text-decoration: none;
}

button {
  font-family: inherit;
  cursor: pointer;
  border: none;
  background: none;
}

img {
  max-width: 100%;
  height: auto;
  display: block;
}

/* Container */
.container {
  width: 100%;
  max-width: 1280px;
  margin: 0 auto;
  padding: 0 var(--space-6);
}

/* Header */
.header {
  position: sticky;
  top: 0;
  z-index: 100;
  background: var(--white);
  border-bottom: 1px solid rgba(0,0,0,0.08);
}

.header-top {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: var(--space-4) 0;
  gap: var(--space-6);
}

.header-logo {
  font-size: var(--font-size-2xl);
  font-weight: 800;
  color: var(--brand-primary);
  letter-spacing: -0.02em;
}

.header-logo span {
  color: var(--foreground);
}

.header-nav {
  display: flex;
  align-items: center;
  gap: var(--space-8);
}

.header-nav a {
  font-size: var(--font-size-sm);
  font-weight: 500;
  color: var(--foreground);
  transition: color var(--transition-fast);
}

.header-nav a:hover {
  color: var(--brand-primary);
}

.header-actions {
  display: flex;
  align-items: center;
  gap: var(--space-4);
}

.search-box {
  display: flex;
  align-items: center;
  gap: var(--space-2);
  padding: var(--space-2) var(--space-4);
  background: var(--bg-muted);
  border-radius: var(--radius-full);
  min-width: 240px;
}

.search-box input {
  border: none;
  background: transparent;
  outline: none;
  font-size: var(--font-size-sm);
  width: 100%;
}

.search-box svg {
  width: 18px;
  height: 18px;
  color: #666;
}

.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: var(--space-2);
  padding: var(--space-3) var(--space-6);
  font-size: var(--font-size-sm);
  font-weight: 600;
  border-radius: var(--radius-full);
  transition: all var(--transition-fast);
}

.btn-primary {
  background: var(--brand-primary);
  color: var(--white);
}

.btn-primary:hover {
  background: var(--brand-primary-dark);
  transform: translateY(-1px);
}

.btn-secondary {
  background: transparent;
  color: var(--foreground);
  border: 1px solid rgba(0,0,0,0.2);
}

.btn-secondary:hover {
  border-color: var(--foreground);
  background: var(--bg-muted);
}

.btn-ghost {
  background: transparent;
  color: var(--foreground);
}

.btn-ghost:hover {
  background: var(--bg-muted);
}

/* Promotional Banner */
.promo-banner {
  background: linear-gradient(135deg, var(--brand-primary) 0%, #FF6B35 100%);
  color: var(--white);
  padding: var(--space-3) 0;
  position: relative;
}

.promo-content {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: var(--space-8);
  text-align: center;
  font-size: var(--font-size-sm);
  font-weight: 500;
}

.promo-content strong {
  font-weight: 700;
}

.promo-close {
  position: absolute;
  right: var(--space-6);
  top: 50%;
  transform: translateY(-50%);
  background: transparent;
  color: var(--white);
  padding: var(--space-2);
  opacity: 0.8;
}

.promo-close:hover {
  opacity: 1;
}

/* Hero Carousel */
.hero-carousel {
  padding: var(--space-16) 0;
  background: var(--bg-surface);
  overflow: hidden;
}

.carousel-wrapper {
  position: relative;
  max-width: 1280px;
  margin: 0 auto;
}

.carousel-track {
  display: flex;
  transition: transform 0.5s ease;
}

.carousel-slide {
  min-width: 100%;
  display: flex;
  align-items: center;
  gap: var(--space-16);
  padding: 0 var(--space-6);
}

.carousel-slide-content {
  flex: 1;
  max-width: 500px;
}

.carousel-slide-content h2 {
  font-size: var(--font-size-4xl);
  font-weight: 800;
  line-height: 1.1;
  margin-bottom: var(--space-4);
  letter-spacing: -0.02em;
}

.carousel-slide-content p {
  font-size: var(--font-size-lg);
  color: #666;
  margin-bottom: var(--space-6);
}

.carousel-slide-image {
  flex: 1;
  max-width: 600px;
  aspect-ratio: 16/10;
  background: var(--bg-muted);
  border-radius: var(--radius-xl);
  overflow: hidden;
}

.carousel-slide-image img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.specialization-badge {
  display: inline-block;
  padding: var(--space-1) var(--space-3);
  background: var(--brand-primary);
  color: var(--white);
  font-size: var(--font-size-xs);
  font-weight: 700;
  border-radius: var(--radius-sm);
  margin-bottom: var(--space-3);
}

.student-count {
  font-size: var(--font-size-sm);
  color: #666;
  margin-bottom: var(--space-2);
}

.rating {
  display: flex;
  align-items: center;
  gap: var(--space-2);
  margin-bottom: var(--space-4);
}

.rating-stars {
  color: #F4B740;
}

.rating-text {
  font-size: var(--font-size-sm);
  color: #666;
}

.price-info {
  display: flex;
  align-items: baseline;
  gap: var(--space-3);
}

.price-sale {
  font-size: var(--font-size-2xl);
  font-weight: 700;
  color: var(--brand-primary);
}

.price-original {
  font-size: var(--font-size-base);
  color: #999;
  text-decoration: line-through;
}

.discount-badge {
  background: #FFEBEB;
  color: var(--brand-primary);
  font-size: var(--font-size-xs);
  font-weight: 700;
  padding: var(--space-1) var(--space-2);
  border-radius: var(--radius-sm);
}

.carousel-nav {
  display: flex;
  justify-content: center;
  align-items: center;
  gap: var(--space-4);
  margin-top: var(--space-8);
}

.carousel-nav button {
  width: 48px;
  height: 48px;
  border-radius: var(--radius-full);
  background: var(--white);
  box-shadow: var(--shadow-md);
  display: flex;
  align-items: center;
  justify-content: center;
  transition: all var(--transition-fast);
}

.carousel-nav button:hover {
  background: var(--bg-muted);
  transform: scale(1.05);
}

.carousel-nav button:disabled {
  opacity: 0.5;
  cursor: not-allowed;
}

.carousel-pagination {
  display: flex;
  gap: var(--space-2);
}

.carousel-dot {
  width: 10px;
  height: 10px;
  border-radius: var(--radius-full);
  background: rgba(0,0,0,0.2);
  transition: all var(--transition-fast);
}

.carousel-dot.active {
  width: 32px;
  background: var(--brand-primary);
}

/* Course Cards */
.course-grid {
  padding: var(--space-16) 0;
}

.section-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: var(--space-8);
}

.section-title {
  font-size: var(--font-size-3xl);
  font-weight: 700;
  letter-spacing: -0.02em;
}

.course-cards {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(280px, 1fr));
  gap: var(--space-6);
}

.course-card {
  background: var(--white);
  border-radius: var(--radius-xl);
  overflow: hidden;
  box-shadow: var(--shadow-md);
  transition: all var(--transition-base);
  cursor: pointer;
}

.course-card:hover {
  transform: translateY(-4px);
  box-shadow: var(--shadow-xl);
}

.course-card-image {
  aspect-ratio: 16/10;
  background: var(--bg-muted);
  overflow: hidden;
}

.course-card-image img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  transition: transform var(--transition-slow);
}

.course-card:hover .course-card-image img {
  transform: scale(1.05);
}

.course-card-content {
  padding: var(--space-5);
}

.course-card-badges {
  display: flex;
  gap: var(--space-2);
  margin-bottom: var(--space-3);
}

.badge {
  font-size: var(--font-size-xs);
  font-weight: 600;
  padding: var(--space-1) var(--space-2);
  border-radius: var(--radius-sm);
}

.badge-bestseller {
  background: #FEF3C7;
  color: #92400E;
}

.badge-free {
  background: #D1FAE5;
  color: #065F46;
}

.course-card-title {
  font-size: var(--font-size-base);
  font-weight: 600;
  margin-bottom: var(--space-2);
  line-height: 1.4;
}

.course-card-instructor {
  font-size: var(--font-size-sm);
  color: #666;
  margin-bottom: var(--space-3);
}

.course-card-stats {
  display: flex;
  align-items: center;
  gap: var(--space-4);
  font-size: var(--font-size-sm);
  color: #666;
  margin-bottom: var(--space-3);
}

.stat-item {
  display: flex;
  align-items: center;
  gap: var(--space-1);
}

.course-card-price {
  display: flex;
  align-items: baseline;
  gap: var(--space-2);
}

.price-current {
  font-size: var(--font-size-xl);
  font-weight: 700;
}

.price-was {
  font-size: var(--font-size-sm);
  color: #999;
  text-decoration: line-through;
}

/* Course Carousel (Horizontal Scroll) */
.course-carousel {
  padding: var(--space-12) 0;
  background: var(--bg-surface);
  overflow: hidden;
}

.course-carousel-track {
  display: flex;
  gap: var(--space-6);
  overflow-x: auto;
  scroll-behavior: smooth;
  padding: var(--space-2);
  -webkit-overflow-scrolling: touch;
}

.course-carousel-track::-webkit-scrollbar {
  display: none;
}

.course-carousel-card {
  min-width: 300px;
  flex-shrink: 0;
}

/* Value Props Section */
.value-props {
  padding: var(--space-20) 0;
}

.value-props-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
  gap: var(--space-8);
}

.value-prop-card {
  text-align: center;
  padding: var(--space-8);
}

.value-prop-icon {
  width: 64px;
  height: 64px;
  margin: 0 auto var(--space-4);
  background: linear-gradient(135deg, var(--brand-primary) 0%, #FF6B35 100%);
  border-radius: var(--radius-xl);
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--white);
}

.value-prop-title {
  font-size: var(--font-size-lg);
  font-weight: 600;
  margin-bottom: var(--space-2);
}

.value-prop-desc {
  font-size: var(--font-size-sm);
  color: #666;
  line-height: 1.6;
}

/* Footer */
.footer {
  background: var(--foreground);
  color: var(--white);
  padding: var(--space-16) 0 var(--space-8);
}

.footer-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: var(--space-12);
  margin-bottom: var(--space-12);
}

.footer-section h4 {
  font-size: var(--font-size-sm);
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  margin-bottom: var(--space-4);
  color: rgba(255,255,255,0.5);
}

.footer-section ul {
  list-style: none;
}

.footer-section li {
  margin-bottom: var(--space-2);
}

.footer-section a {
  font-size: var(--font-size-sm);
  color: rgba(255,255,255,0.8);
  transition: color var(--transition-fast);
}

.footer-section a:hover {
  color: var(--white);
}

.footer-bottom {
  padding-top: var(--space-8);
  border-top: 1px solid rgba(255,255,255,0.1);
  display: flex;
  justify-content: space-between;
  align-items: center;
}

.footer-bottom p {
  font-size: var(--font-size-sm);
  color: rgba(255,255,255,0.5);
}

.footer-legal {
  display: flex;
  gap: var(--space-6);
}

.footer-legal a {
  font-size: var(--font-size-sm);
  color: rgba(255,255,255,0.5);
  transition: color var(--transition-fast);
}

.footer-legal a:hover {
  color: var(--white);
}

/* Footer Accordion (Mobile) */
.footer-accordion {
  display: none;
}

.footer-accordion-item {
  border-bottom: 1px solid rgba(255,255,255,0.1);
}

.footer-accordion-header {
  width: 100%;
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: var(--space-4) 0;
  color: var(--white);
  font-weight: 600;
  text-align: left;
}

.footer-accordion-icon {
  transition: transform var(--transition-fast);
}

.footer-accordion-item.open .footer-accordion-icon {
  transform: rotate(180deg);
}

.footer-accordion-content {
  max-height: 0;
  overflow: hidden;
  transition: max-height var(--transition-base);
}

.footer-accordion-item.open .footer-accordion-content {
  max-height: 500px;
}

.footer-accordion-content ul {
  padding-bottom: var(--space-4);
}

/* Responsive */
@media (max-width: 1024px) {
  .header-nav {
    display: none;
  }

  .mobile-nav-toggle {
    display: flex;
  }

  .search-box {
    min-width: 180px;
  }

  .carousel-slide {
    flex-direction: column;
    text-align: center;
    gap: var(--space-8);
  }

  .carousel-slide-content {
    max-width: 100%;
  }

  .carousel-slide-image {
    max-width: 100%;
  }

  .footer-grid {
    grid-template-columns: repeat(2, 1fr);
  }
}

@media (max-width: 768px) {
  .promo-content {
    flex-direction: column;
    gap: var(--space-2);
  }

  .section-header {
    flex-direction: column;
    align-items: flex-start;
    gap: var(--space-4);
  }

  .course-cards {
    grid-template-columns: 1fr;
  }

  .footer-grid {
    display: none;
  }

  .footer-accordion {
    display: block;
  }

  .footer-bottom {
    flex-direction: column;
    gap: var(--space-4);
    text-align: center;
  }

  .footer-legal {
    flex-wrap: wrap;
    justify-content: center;
  }
}

/* Plus Page Styles */
.pricing-section {
  padding: var(--space-16) 0;
  background: var(--bg-surface);
}

.pricing-header {
  text-align: center;
  margin-bottom: var(--space-12);
}

.pricing-header h2 {
  font-size: var(--font-size-4xl);
  font-weight: 800;
  margin-bottom: var(--space-4);
}

.pricing-header p {
  font-size: var(--font-size-lg);
  color: #666;
}

.pricing-toggle {
  display: flex;
  justify-content: center;
  align-items: center;
  gap: var(--space-4);
  margin-bottom: var(--space-10);
}

.toggle-label {
  font-size: var(--font-size-sm);
  font-weight: 500;
  color: #666;
}

.toggle-label.active {
  color: var(--foreground);
  font-weight: 700;
}

.toggle-switch {
  position: relative;
  width: 56px;
  height: 30px;
  background: #ddd;
  border-radius: var(--radius-full);
  cursor: pointer;
  transition: background var(--transition-fast);
}

.toggle-switch.active {
  background: var(--brand-primary);
}

.toggle-switch::after {
  content: '';
  position: absolute;
  top: 3px;
  left: 3px;
  width: 24px;
  height: 24px;
  background: var(--white);
  border-radius: var(--radius-full);
  transition: transform var(--transition-fast);
}

.toggle-switch.active::after {
  transform: translateX(26px);
}

.pricing-cards {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: var(--space-6);
  max-width: 800px;
  margin: 0 auto;
}

.pricing-card {
  background: var(--white);
  border-radius: var(--radius-xl);
  padding: var(--space-8);
  box-shadow: var(--shadow-lg);
  position: relative;
}

.pricing-card.featured {
  border: 2px solid var(--brand-primary);
}

.pricing-card.featured::before {
  content: 'Best Value';
  position: absolute;
  top: -12px;
  left: 50%;
  transform: translateX(-50%);
  background: var(--brand-primary);
  color: var(--white);
  padding: var(--space-1) var(--space-4);
  border-radius: var(--radius-full);
  font-size: var(--font-size-xs);
  font-weight: 700;
}

.plan-name {
  font-size: var(--font-size-lg);
  font-weight: 600;
  margin-bottom: var(--space-4);
}

.plan-price {
  margin-bottom: var(--space-4);
}

.plan-price .amount {
  font-size: var(--font-size-4xl);
  font-weight: 800;
}

.plan-price .period {
  font-size: var(--font-size-base);
  color: #666;
}

.plan-billed {
  font-size: var(--font-size-sm);
  color: #666;
  margin-bottom: var(--space-4);
}

.plan-savings {
  display: inline-block;
  background: #D1FAE5;
  color: #065F46;
  padding: var(--space-1) var(--space-3);
  border-radius: var(--radius-full);
  font-size: var(--font-size-xs);
  font-weight: 700;
  margin-bottom: var(--space-6);
}

.plan-features {
  list-style: none;
  margin-bottom: var(--space-6);
}

.plan-features li {
  display: flex;
  align-items: center;
  gap: var(--space-3);
  font-size: var(--font-size-sm);
  margin-bottom: var(--space-3);
}

.plan-features li svg {
  width: 18px;
  height: 18px;
  color: var(--brand-primary);
  flex-shrink: 0;
}

/* FAQ Accordion */
.faq-section {
  padding: var(--space-16) 0;
}

.faq-header {
  text-align: center;
  margin-bottom: var(--space-10);
}

.faq-header h2 {
  font-size: var(--font-size-3xl);
  font-weight: 700;
}

.faq-list {
  max-width: 800px;
  margin: 0 auto;
}

.faq-item {
  border-bottom: 1px solid rgba(0,0,0,0.1);
}

.faq-question {
  width: 100%;
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: var(--space-5) 0;
  font-size: var(--font-size-base);
  font-weight: 600;
  text-align: left;
}

.faq-icon {
  transition: transform var(--transition-fast);
}

.faq-item.open .faq-icon {
  transform: rotate(180deg);
}

.faq-answer {
  max-height: 0;
  overflow: hidden;
  transition: max-height var(--transition-base);
}

.faq-item.open .faq-answer {
  max-height: 300px;
}

.faq-answer p {
  padding-bottom: var(--space-5);
  color: #666;
  line-height: 1.7;
}

/* Credits Carousel */
.credits-carousel {
  padding: var(--space-12) 0;
}

.credits-track {
  display: flex;
  gap: var(--space-6);
  overflow-x: auto;
  scroll-behavior: smooth;
  padding: var(--space-2);
  -webkit-overflow-scrolling: touch;
}

.credits-track::-webkit-scrollbar {
  display: none;
}

.credit-card {
  min-width: 300px;
  flex-shrink: 0;
  background: var(--white);
  border-radius: var(--radius-xl);
  padding: var(--space-6);
  box-shadow: var(--shadow-md);
}

/* Certificates Section */
.certificates {
  padding: var(--space-16) 0;
  background: var(--bg-surface);
}

.cert-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: var(--space-6);
}

.cert-card {
  background: var(--white);
  border-radius: var(--radius-xl);
  padding: var(--space-8);
  text-align: center;
  box-shadow: var(--shadow-md);
}

.cert-card-icon {
  width: 80px;
  height: 80px;
  margin: 0 auto var(--space-4);
  background: linear-gradient(135deg, var(--brand-primary) 0%, #FF6B35 100%);
  border-radius: var(--radius-xl);
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--white);
}

.cert-card h3 {
  font-size: var(--font-size-xl);
  font-weight: 700;
  margin-bottom: var(--space-2);
}

.cert-card p {
  font-size: var(--font-size-sm);
  color: #666;
}

/* Mobile Nav */
.mobile-nav-toggle {
  display: none;
  flex-direction: column;
  gap: 5px;
  padding: var(--space-2);
}

.mobile-nav-toggle span {
  width: 24px;
  height: 2px;
  background: var(--foreground);
  border-radius: 2px;
}

@media (max-width: 768px) {
  .pricing-cards {
    grid-template-columns: 1fr;
  }

  .cert-grid {
    grid-template-columns: 1fr;
  }

  .value-props-grid {
    grid-template-columns: 1fr;
  }
}

/* Login Page */
.login-page {
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--bg-surface);
  padding: var(--space-6);
}

.login-container {
  width: 100%;
  max-width: 420px;
}

.login-box {
  background: var(--white);
  border-radius: var(--radius-2xl);
  padding: var(--space-10);
  box-shadow: var(--shadow-xl);
}

.login-header {
  text-align: center;
  margin-bottom: var(--space-8);
}

.login-header h1 {
  font-size: var(--font-size-3xl);
  font-weight: 800;
  margin-bottom: var(--space-2);
}

.login-header p {
  color: #666;
}

.social-login {
  display: flex;
  flex-direction: column;
  gap: var(--space-3);
  margin-bottom: var(--space-6);
}

.social-btn {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: var(--space-3);
  width: 100%;
  padding: var(--space-4);
  border-radius: var(--radius-lg);
  font-size: var(--font-size-sm);
  font-weight: 600;
  transition: all var(--transition-fast);
}

.social-btn-facebook {
  background: #1877F2;
  color: var(--white);
}

.social-btn-apple {
  background: var(--foreground);
  color: var(--white);
}

.social-btn:hover {
  opacity: 0.9;
  transform: translateY(-1px);
}

.divider {
  display: flex;
  align-items: center;
  gap: var(--space-4);
  margin-bottom: var(--space-6);
  color: #999;
  font-size: var(--font-size-sm);
}

.divider::before,
.divider::after {
  content: '';
  flex: 1;
  height: 1px;
  background: rgba(0,0,0,0.1);
}

.form-group {
  margin-bottom: var(--space-5);
}

.form-group label {
  display: block;
  font-size: var(--font-size-sm);
  font-weight: 500;
  margin-bottom: var(--space-2);
}

.form-group input {
  width: 100%;
  padding: var(--space-4);
  border: 1px solid rgba(0,0,0,0.1);
  border-radius: var(--radius-lg);
  font-size: var(--font-size-base);
  transition: border-color var(--transition-fast);
}

.form-group input:focus {
  outline: none;
  border-color: var(--brand-primary);
}

.password-field {
  position: relative;
}

.password-toggle {
  position: absolute;
  right: var(--space-4);
  top: 50%;
  transform: translateY(-50%);
  color: #666;
}

.forgot-link {
  display: block;
  text-align: right;
  font-size: var(--font-size-sm);
  color: var(--brand-primary);
  margin-bottom: var(--space-6);
}

.login-submit {
  width: 100%;
  padding: var(--space-4);
  background: var(--brand-primary);
  color: var(--white);
  font-size: var(--font-size-base);
  font-weight: 700;
  border-radius: var(--radius-lg);
  transition: all var(--transition-fast);
}

.login-submit:hover {
  background: var(--brand-primary-dark);
}

.login-footer {
  text-align: center;
  margin-top: var(--space-6);
  font-size: var(--font-size-sm);
  color: #666;
}

.login-footer a {
  color: var(--brand-primary);
  font-weight: 600;
}

/* Projects Page */
.projects-page {
  background: var(--bg-surface);
  min-height: 100vh;
}

.projects-hero {
  background: var(--foreground);
  color: var(--white);
  padding: var(--space-16) 0;
  text-align: center;
}

.projects-hero h1 {
  font-size: var(--font-size-4xl);
  font-weight: 800;
  margin-bottom: var(--space-4);
}

.projects-hero p {
  font-size: var(--font-size-lg);
  color: rgba(255,255,255,0.7);
}

.projects-filters {
  padding: var(--space-8) 0;
  background: var(--white);
  border-bottom: 1px solid rgba(0,0,0,0.08);
  position: sticky;
  top: 72px;
  z-index: 50;
}

.filter-row {
  display: flex;
  align-items: center;
  gap: var(--space-4);
  flex-wrap: wrap;
}

.filter-group {
  display: flex;
  align-items: center;
  gap: var(--space-2);
}

.filter-label {
  font-size: var(--font-size-sm);
  font-weight: 500;
  color: #666;
}

.filter-select {
  padding: var(--space-2) var(--space-4);
  border: 1px solid rgba(0,0,0,0.1);
  border-radius: var(--radius-full);
  font-size: var(--font-size-sm);
  background: var(--white);
  cursor: pointer;
}

.filter-btn {
  padding: var(--space-2) var(--space-4);
  border-radius: var(--radius-full);
  font-size: var(--font-size-sm);
  font-weight: 500;
  background: var(--bg-muted);
  color: var(--foreground);
  transition: all var(--transition-fast);
}

.filter-btn:hover,
.filter-btn.active {
  background: var(--foreground);
  color: var(--white);
}

.projects-gallery {
  padding: var(--space-12) 0;
}

.masonry-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: var(--space-6);
}

.masonry-item {
  background: var(--white);
  border-radius: var(--radius-xl);
  overflow: hidden;
  box-shadow: var(--shadow-md);
  transition: all var(--transition-base);
}

.masonry-item:hover {
  transform: translateY(-4px);
  box-shadow: var(--shadow-xl);
}

.masonry-item-image {
  aspect-ratio: 1;
  background: var(--bg-muted);
  overflow: hidden;
}

.masonry-item-image img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.masonry-item-content {
  padding: var(--space-4);
}

.masonry-item-title {
  font-size: var(--font-size-base);
  font-weight: 600;
  margin-bottom: var(--space-1);
}

.masonry-item-author {
  font-size: var(--font-size-sm);
  color: #666;
  margin-bottom: var(--space-3);
}

.masonry-item-stats {
  display: flex;
  gap: var(--space-4);
  font-size: var(--font-size-sm);
  color: #666;
}

@media (max-width: 1024px) {
  .masonry-grid {
    grid-template-columns: repeat(3, 1fr);
  }
}

@media (max-width: 768px) {
  .masonry-grid {
    grid-template-columns: repeat(2, 1fr);
  }

  .filter-row {
    flex-direction: column;
    align-items: flex-start;
  }
}

@media (max-width: 480px) {
  .masonry-grid {
    grid-template-columns: 1fr;
  }
}

/* Courses Page */
.courses-page {
  background: var(--bg-surface);
}

.courses-hero {
  background: var(--foreground);
  color: var(--white);
  padding: var(--space-12) 0;
  text-align: center;
}

.courses-hero h1 {
  font-size: var(--font-size-4xl);
  font-weight: 800;
}

.courses-layout {
  display: grid;
  grid-template-columns: 280px 1fr;
  gap: var(--space-8);
  padding: var(--space-8) 0;
}

.sidebar-nav {
  background: var(--white);
  border-radius: var(--radius-xl);
  padding: var(--space-6);
  height: fit-content;
  position: sticky;
  top: 100px;
}

.sidebar-section {
  margin-bottom: var(--space-6);
}

.sidebar-section:last-child {
  margin-bottom: 0;
}

.sidebar-title {
  font-size: var(--font-size-xs);
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  color: #666;
  margin-bottom: var(--space-3);
}

.sidebar-list {
  list-style: none;
}

.sidebar-list li {
  margin-bottom: var(--space-2);
}

.sidebar-list button {
  width: 100%;
  text-align: left;
  padding: var(--space-2) var(--space-3);
  border-radius: var(--radius-md);
  font-size: var(--font-size-sm);
  color: var(--foreground);
  transition: all var(--transition-fast);
}

.sidebar-list button:hover,
.sidebar-list button.active {
  background: var(--brand-primary);
  color: var(--white);
}

.courses-content {
  min-width: 0;
}

.category-section {
  margin-bottom: var(--space-12);
}

.category-title {
  font-size: var(--font-size-2xl);
  font-weight: 700;
  margin-bottom: var(--space-6);
  padding-bottom: var(--space-3);
  border-bottom: 2px solid var(--brand-primary);
}

.course-row {
  display: flex;
  gap: var(--space-4);
  overflow-x: auto;
  padding: var(--space-2);
  -webkit-overflow-scrolling: touch;
}

.course-row::-webkit-scrollbar {
  display: none;
}

.course-row-card {
  min-width: 280px;
  flex-shrink: 0;
}

@media (max-width: 1024px) {
  .courses-layout {
    grid-template-columns: 1fr;
  }

  .sidebar-nav {
    position: static;
  }
}

/* Hero CTA Section */
.hero-cta {
  padding: var(--space-16) 0;
  text-align: center;
  background: linear-gradient(135deg, var(--brand-primary) 0%, #FF6B35 100%);
  color: var(--white);
}

.hero-cta h1 {
  font-size: var(--font-size-5xl);
  font-weight: 800;
  margin-bottom: var(--space-4);
}

.hero-cta p {
  font-size: var(--font-size-xl);
  margin-bottom: var(--space-8);
  opacity: 0.9;
}

.hero-cta-buttons {
  display: flex;
  justify-content: center;
  gap: var(--space-4);
}

.btn-white {
  background: var(--white);
  color: var(--brand-primary);
  padding: var(--space-4) var(--space-8);
  font-size: var(--font-size-lg);
  font-weight: 700;
  border-radius: var(--radius-full);
  transition: all var(--transition-fast);
}

.btn-white:hover {
  transform: translateY(-2px);
  box-shadow: var(--shadow-lg);
}

.btn-outline-white {
  background: transparent;
  color: var(--white);
  padding: var(--space-4) var(--space-8);
  font-size: var(--font-size-lg);
  font-weight: 700;
  border: 2px solid var(--white);
  border-radius: var(--radius-full);
  transition: all var(--transition-fast);
}

.btn-outline-white:hover {
  background: var(--white);
  color: var(--brand-primary);
}

/* Credits Features Section */
.credits-features {
  padding: var(--space-16) 0;
}

.credits-header {
  text-align: center;
  margin-bottom: var(--space-10);
}

.credits-header h2 {
  font-size: var(--font-size-3xl);
  font-weight: 700;
}

/* Pricing Comparison */
.pricing-comparison {
  padding: var(--space-16) 0;
  background: var(--bg-surface);
}

.comparison-table {
  width: 100%;
  max-width: 900px;
  margin: 0 auto;
  background: var(--white);
  border-radius: var(--radius-xl);
  overflow: hidden;
  box-shadow: var(--shadow-lg);
}

.comparison-header {
  display: grid;
  grid-template-columns: 2fr 1fr 1fr;
  background: var(--foreground);
  color: var(--white);
}

.comparison-header > div {
  padding: var(--space-5);
  font-weight: 600;
  text-align: center;
}

.comparison-header > div:first-child {
  text-align: left;
}

.comparison-row {
  display: grid;
  grid-template-columns: 2fr 1fr 1fr;
  border-bottom: 1px solid rgba(0,0,0,0.05);
}

.comparison-row:last-child {
  border-bottom: none;
}

.comparison-row > div {
  padding: var(--space-4) var(--space-5);
  text-align: center;
  display: flex;
  align-items: center;
  justify-content: center;
}

.comparison-row > div:first-child {
  justify-content: flex-start;
}

.check-icon {
  color: #22C55E;
}

.x-icon {
  color: #EF4444;
}

/* CreativeHub Design System */
@import url('https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800&display=swap');

:root {
  /* Brand Colors */
  --brand-primary: #F02D00;
  --brand-primary-dark: #D02800;
  --brand-primary-light: #FF4D2E;
  --foreground: #171717;
  --white: #FFFFFF;
  --bg-surface: #FAFAFA;
  --bg-elevated: #FFFFFF;
  --bg-muted: #F5F5F5;

  /* OKLCH Conversions for reference */
  /* --brand-primary: oklch(55% 0.22 25); */
  /* --foreground: oklch(10% 0.01 265); */

  /* Typography */
  --font-family: 'Inter', -apple-system, BlinkMacSystemFont, sans-serif;
  --font-size-xs: 0.75rem;
  --font-size-sm: 0.875rem;
  --font-size-base: 1rem;
  --font-size-lg: 1.125rem;
  --font-size-xl: 1.25rem;
  --font-size-2xl: 1.5rem;
  --font-size-3xl: 1.875rem;
  --font-size-4xl: 2.25rem;
  --font-size-5xl: 3rem;
  --font-size-6xl: 3.75rem;

  /* Spacing */
  --space-1: 0.25rem;
  --space-2: 0.5rem;
  --space-3: 0.75rem;
  --space-4: 1rem;
  --space-5: 1.25rem;
  --space-6: 1.5rem;
  --space-8: 2rem;
  --space-10: 2.5rem;
  --space-12: 3rem;
  --space-16: 4rem;
  --space-20: 5rem;
  --space-24: 6rem;

  /* Border Radius */
  --radius-sm: 0.25rem;
  --radius-md: 0.5rem;
  --radius-lg: 0.75rem;
  --radius-xl: 1rem;
  --radius-2xl: 1.5rem;
  --radius-full: 9999px;

  /* Shadows */
  --shadow-sm: 0 1px 2px rgba(0,0,0,0.05);
  --shadow-md: 0 4px 6px -1px rgba(0,0,0,0.1), 0 2px 4px -2px rgba(0,0,0,0.1);
  --shadow-lg: 0 10px 15px -3px rgba(0,0,0,0.1), 0 4px 6px -4px rgba(0,0,0,0.1);
  --shadow-xl: 0 20px 25px -5px rgba(0,0,0,0.1), 0 8px 10px -6px rgba(0,0,0,0.1);

  /* Transitions */
  --transition-fast: 150ms ease;
  --transition-base: 200ms ease;
  --transition-slow: 300ms ease;
}

/* Reset & Base */
*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html {
  font-size: 16px;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

body {
  font-family: var(--font-family);
  font-size: var(--font-size-base);
  line-height: 1.6;
  color: var(--foreground);
  background-color: var(--white);
}

a {
  color: inherit;
  text-decoration: none;
}

button {
  font-family: inherit;
  cursor: pointer;
  border: none;
  background: none;
}

img {
  max-width: 100%;
  height: auto;
  display: block;
}

/* Container */
.container {
  width: 100%;
  max-width: 1280px;
  margin: 0 auto;
  padding: 0 var(--space-6);
}

/* Header */
.header {
  position: sticky;
  top: 0;
  z-index: 100;
  background: var(--white);
  border-bottom: 1px solid rgba(0,0,0,0.08);
}

.header-top {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: var(--space-4) 0;
  gap: var(--space-6);
}

.header-logo {
  font-size: var(--font-size-2xl);
  font-weight: 800;
  color: var(--brand-primary);
  letter-spacing: -0.02em;
}

.header-logo span {
  color: var(--foreground);
}

.header-nav {
  display: flex;
  align-items: center;
  gap: var(--space-8);
}

.header-nav a {
  font-size: var(--font-size-sm);
  font-weight: 500;
  color: var(--foreground);
  transition: color var(--transition-fast);
}

.header-nav a:hover {
  color: var(--brand-primary);
}

.header-actions {
  display: flex;
  align-items: center;
  gap: var(--space-4);
}

.search-box {
  display: flex;
  align-items: center;
  gap: var(--space-2);
  padding: var(--space-2) var(--space-4);
  background: var(--bg-muted);
  border-radius: var(--radius-full);
  min-width: 240px;
}

.search-box input {
  border: none;
  background: transparent;
  outline: none;
  font-size: var(--font-size-sm);
  width: 100%;
}

.search-box svg {
  width: 18px;
  height: 18px;
  color: #666;
}

.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: var(--space-2);
  padding: var(--space-3) var(--space-6);
  font-size: var(--font-size-sm);
  font-weight: 600;
  border-radius: var(--radius-full);
  transition: all var(--transition-fast);
}

.btn-primary {
  background: var(--brand-primary);
  color: var(--white);
}

.btn-primary:hover {
  background: var(--brand-primary-dark);
  transform: translateY(-1px);
}

.btn-secondary {
  background: transparent;
  color: var(--foreground);
  border: 1px solid rgba(0,0,0,0.2);
}

.btn-secondary:hover {
  border-color: var(--foreground);
  background: var(--bg-muted);
}

.btn-ghost {
  background: transparent;
  color: var(--foreground);
}

.btn-ghost:hover {
  background: var(--bg-muted);
}

/* Promotional Banner */
.promo-banner {
  background: linear-gradient(135deg, var(--brand-primary) 0%, #FF6B35 100%);
  color: var(--white);
  padding: var(--space-3) 0;
  position: relative;
}

.promo-content {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: var(--space-8);
  text-align: center;
  font-size: var(--font-size-sm);
  font-weight: 500;
}

.promo-content strong {
  font-weight: 700;
}

.promo-close {
  position: absolute;
  right: var(--space-6);
  top: 50%;
  transform: translateY(-50%);
  background: transparent;
  color: var(--white);
  padding: var(--space-2);
  opacity: 0.8;
}

.promo-close:hover {
  opacity: 1;
}

/* Hero Carousel */
.hero-carousel {
  padding: var(--space-16) 0;
  background: var(--bg-surface);
  overflow: hidden;
}

.carousel-wrapper {
  position: relative;
  max-width: 1280px;
  margin: 0 auto;
}

.carousel-track {
  display: flex;
  transition: transform 0.5s ease;
}

.carousel-slide {
  min-width: 100%;
  display: flex;
  align-items: center;
  gap: var(--space-16);
  padding: 0 var(--space-6);
}

.carousel-slide-content {
  flex: 1;
  max-width: 500px;
}

.carousel-slide-content h2 {
  font-size: var(--font-size-4xl);
  font-weight: 800;
  line-height: 1.1;
  margin-bottom: var(--space-4);
  letter-spacing: -0.02em;
}

.carousel-slide-content p {
  font-size: var(--font-size-lg);
  color: #666;
  margin-bottom: var(--space-6);
}

.carousel-slide-image {
  flex: 1;
  max-width: 600px;
  aspect-ratio: 16/10;
  background: var(--bg-muted);
  border-radius: var(--radius-xl);
  overflow: hidden;
}

.carousel-slide-image img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.specialization-badge {
  display: inline-block;
  padding: var(--space-1) var(--space-3);
  background: var(--brand-primary);
  color: var(--white);
  font-size: var(--font-size-xs);
  font-weight: 700;
  border-radius: var(--radius-sm);
  margin-bottom: var(--space-3);
}

.student-count {
  font-size: var(--font-size-sm);
  color: #666;
  margin-bottom: var(--space-2);
}

.rating {
  display: flex;
  align-items: center;
  gap: var(--space-2);
  margin-bottom: var(--space-4);
}

.rating-stars {
  color: #F4B740;
}

.rating-text {
  font-size: var(--font-size-sm);
  color: #666;
}

.price-info {
  display: flex;
  align-items: baseline;
  gap: var(--space-3);
}

.price-sale {
  font-size: var(--font-size-2xl);
  font-weight: 700;
  color: var(--brand-primary);
}

.price-original {
  font-size: var(--font-size-base);
  color: #999;
  text-decoration: line-through;
}

.discount-badge {
  background: #FFEBEB;
  color: var(--brand-primary);
  font-size: var(--font-size-xs);
  font-weight: 700;
  padding: var(--space-1) var(--space-2);
  border-radius: var(--radius-sm);
}

.carousel-nav {
  display: flex;
  justify-content: center;
  align-items: center;
  gap: var(--space-4);
  margin-top: var(--space-8);
}

.carousel-nav button {
  width: 48px;
  height: 48px;
  border-radius: var(--radius-full);
  background: var(--white);
  box-shadow: var(--shadow-md);
  display: flex;
  align-items: center;
  justify-content: center;
  transition: all var(--transition-fast);
}

.carousel-nav button:hover {
  background: var(--bg-muted);
  transform: scale(1.05);
}

.carousel-nav button:disabled {
  opacity: 0.5;
  cursor: not-allowed;
}

.carousel-pagination {
  display: flex;
  gap: var(--space-2);
}

.carousel-dot {
  width: 10px;
  height: 10px;
  border-radius: var(--radius-full);
  background: rgba(0,0,0,0.2);
  transition: all var(--transition-fast);
}

.carousel-dot.active {
  width: 32px;
  background: var(--brand-primary);
}

/* Course Cards */
.course-grid {
  padding: var(--space-16) 0;
}

.section-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: var(--space-8);
}

.section-title {
  font-size: var(--font-size-3xl);
  font-weight: 700;
  letter-spacing: -0.02em;
}

.course-cards {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(280px, 1fr));
  gap: var(--space-6);
}

.course-card {
  background: var(--white);
  border-radius: var(--radius-xl);
  overflow: hidden;
  box-shadow: var(--shadow-md);
  transition: all var(--transition-base);
  cursor: pointer;
}

.course-card:hover {
  transform: translateY(-4px);
  box-shadow: var(--shadow-xl);
}

.course-card-image {
  aspect-ratio: 16/10;
  background: var(--bg-muted);
  overflow: hidden;
}

.course-card-image img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  transition: transform var(--transition-slow);
}

.course-card:hover .course-card-image img {
  transform: scale(1.05);
}

.course-card-content {
  padding: var(--space-5);
}

.course-card-badges {
  display: flex;
  gap: var(--space-2);
  margin-bottom: var(--space-3);
}

.badge {
  font-size: var(--font-size-xs);
  font-weight: 600;
  padding: var(--space-1) var(--space-2);
  border-radius: var(--radius-sm);
}

.badge-bestseller {
  background: #FEF3C7;
  color: #92400E;
}

.badge-free {
  background: #D1FAE5;
  color: #065F46;
}

.course-card-title {
  font-size: var(--font-size-base);
  font-weight: 600;
  margin-bottom: var(--space-2);
  line-height: 1.4;
}

.course-card-instructor {
  font-size: var(--font-size-sm);
  color: #666;
  margin-bottom: var(--space-3);
}

.course-card-stats {
  display: flex;
  align-items: center;
  gap: var(--space-4);
  font-size: var(--font-size-sm);
  color: #666;
  margin-bottom: var(--space-3);
}

.stat-item {
  display: flex;
  align-items: center;
  gap: var(--space-1);
}

.course-card-price {
  display: flex;
  align-items: baseline;
  gap: var(--space-2);
}

.price-current {
  font-size: var(--font-size-xl);
  font-weight: 700;
}

.price-was {
  font-size: var(--font-size-sm);
  color: #999;
  text-decoration: line-through;
}

/* Course Carousel (Horizontal Scroll) */
.course-carousel {
  padding: var(--space-12) 0;
  background: var(--bg-surface);
  overflow: hidden;
}

.course-carousel-track {
  display: flex;
  gap: var(--space-6);
  overflow-x: auto;
  scroll-behavior: smooth;
  padding: var(--space-2);
  -webkit-overflow-scrolling: touch;
}

.course-carousel-track::-webkit-scrollbar {
  display: none;
}

.course-carousel-card {
  min-width: 300px;
  flex-shrink: 0;
}

/* Value Props Section */
.value-props {
  padding: var(--space-20) 0;
}

.value-props-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
  gap: var(--space-8);
}

.value-prop-card {
  text-align: center;
  padding: var(--space-8);
}

.value-prop-icon {
  width: 64px;
  height: 64px;
  margin: 0 auto var(--space-4);
  background: linear-gradient(135deg, var(--brand-primary) 0%, #FF6B35 100%);
  border-radius: var(--radius-xl);
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--white);
}

.value-prop-title {
  font-size: var(--font-size-lg);
  font-weight: 600;
  margin-bottom: var(--space-2);
}

.value-prop-desc {
  font-size: var(--font-size-sm);
  color: #666;
  line-height: 1.6;
}

/* Footer */
.footer {
  background: var(--foreground);
  color: var(--white);
  padding: var(--space-16) 0 var(--space-8);
}

.footer-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: var(--space-12);
  margin-bottom: var(--space-12);
}

.footer-section h4 {
  font-size: var(--font-size-sm);
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  margin-bottom: var(--space-4);
  color: rgba(255,255,255,0.5);
}

.footer-section ul {
  list-style: none;
}

.footer-section li {
  margin-bottom: var(--space-2);
}

.footer-section a {
  font-size: var(--font-size-sm);
  color: rgba(255,255,255,0.8);
  transition: color var(--transition-fast);
}

.footer-section a:hover {
  color: var(--white);
}

.footer-bottom {
  padding-top: var(--space-8);
  border-top: 1px solid rgba(255,255,255,0.1);
  display: flex;
  justify-content: space-between;
  align-items: center;
}

.footer-bottom p {
  font-size: var(--font-size-sm);
  color: rgba(255,255,255,0.5);
}

.footer-legal {
  display: flex;
  gap: var(--space-6);
}

.footer-legal a {
  font-size: var(--font-size-sm);
  color: rgba(255,255,255,0.5);
  transition: color var(--transition-fast);
}

.footer-legal a:hover {
  color: var(--white);
}

/* Footer Accordion (Mobile) */
.footer-accordion {
  display: none;
}

.footer-accordion-item {
  border-bottom: 1px solid rgba(255,255,255,0.1);
}

.footer-accordion-header {
  width: 100%;
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: var(--space-4) 0;
  color: var(--white);
  font-weight: 600;
  text-align: left;
}

.footer-accordion-icon {
  transition: transform var(--transition-fast);
}

.footer-accordion-item.open .footer-accordion-icon {
  transform: rotate(180deg);
}

.footer-accordion-content {
  max-height: 0;
  overflow: hidden;
  transition: max-height var(--transition-base);
}

.footer-accordion-item.open .footer-accordion-content {
  max-height: 500px;
}

.footer-accordion-content ul {
  padding-bottom: var(--space-4);
}

/* Responsive */
@media (max-width: 1024px) {
  .header-nav {
    display: none;
  }

  .mobile-nav-toggle {
    display: flex;
  }

  .search-box {
    min-width: 180px;
  }

  .carousel-slide {
    flex-direction: column;
    text-align: center;
    gap: var(--space-8);
  }

  .carousel-slide-content {
    max-width: 100%;
  }

  .carousel-slide-image {
    max-width: 100%;
  }

  .footer-grid {
    grid-template-columns: repeat(2, 1fr);
  }
}

@media (max-width: 768px) {
  .promo-content {
    flex-direction: column;
    gap: var(--space-2);
  }

  .section-header {
    flex-direction: column;
    align-items: flex-start;
    gap: var(--space-4);
  }

  .course-cards {
    grid-template-columns: 1fr;
  }

  .footer-grid {
    display: none;
  }

  .footer-accordion {
    display: block;
  }

  .footer-bottom {
    flex-direction: column;
    gap: var(--space-4);
    text-align: center;
  }

  .footer-legal {
    flex-wrap: wrap;
    justify-content: center;
  }
}

/* Plus Page Styles */
.pricing-section {
  padding: var(--space-16) 0;
  background: var(--bg-surface);
}

.pricing-header {
  text-align: center;
  margin-bottom: var(--space-12);
}

.pricing-header h2 {
  font-size: var(--font-size-4xl);
  font-weight: 800;
  margin-bottom: var(--space-4);
}

.pricing-header p {
  font-size: var(--font-size-lg);
  color: #666;
}

.pricing-toggle {
  display: flex;
  justify-content: center;
  align-items: center;
  gap: var(--space-4);
  margin-bottom: var(--space-10);
}

.toggle-label {
  font-size: var(--font-size-sm);
  font-weight: 500;
  color: #666;
}

.toggle-label.active {
  color: var(--foreground);
  font-weight: 700;
}

.toggle-switch {
  position: relative;
  width: 56px;
  height: 30px;
  background: #ddd;
  border-radius: var(--radius-full);
  cursor: pointer;
  transition: background var(--transition-fast);
}

.toggle-switch.active {
  background: var(--brand-primary);
}

.toggle-switch::after {
  content: '';
  position: absolute;
  top: 3px;
  left: 3px;
  width: 24px;
  height: 24px;
  background: var(--white);
  border-radius: var(--radius-full);
  transition: transform var(--transition-fast);
}

.toggle-switch.active::after {
  transform: translateX(26px);
}

.pricing-cards {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: var(--space-6);
  max-width: 800px;
  margin: 0 auto;
}

.pricing-card {
  background: var(--white);
  border-radius: var(--radius-xl);
  padding: var(--space-8);
  box-shadow: var(--shadow-lg);
  position: relative;
}

.pricing-card.featured {
  border: 2px solid var(--brand-primary);
}

.pricing-card.featured::before {
  content: 'Best Value';
  position: absolute;
  top: -12px;
  left: 50%;
  transform: translateX(-50%);
  background: var(--brand-primary);
  color: var(--white);
  padding: var(--space-1) var(--space-4);
  border-radius: var(--radius-full);
  font-size: var(--font-size-xs);
  font-weight: 700;
}

.plan-name {
  font-size: var(--font-size-lg);
  font-weight: 600;
  margin-bottom: var(--space-4);
}

.plan-price {
  margin-bottom: var(--space-4);
}

.plan-price .amount {
  font-size: var(--font-size-4xl);
  font-weight: 800;
}

.plan-price .period {
  font-size: var(--font-size-base);
  color: #666;
}

.plan-billed {
  font-size: var(--font-size-sm);
  color: #666;
  margin-bottom: var(--space-4);
}

.plan-savings {
  display: inline-block;
  background: #D1FAE5;
  color: #065F46;
  padding: var(--space-1) var(--space-3);
  border-radius: var(--radius-full);
  font-size: var(--font-size-xs);
  font-weight: 700;
  margin-bottom: var(--space-6);
}

.plan-features {
  list-style: none;
  margin-bottom: var(--space-6);
}

.plan-features li {
  display: flex;
  align-items: center;
  gap: var(--space-3);
  font-size: var(--font-size-sm);
  margin-bottom: var(--space-3);
}

.plan-features li svg {
  width: 18px;
  height: 18px;
  color: var(--brand-primary);
  flex-shrink: 0;
}

/* FAQ Accordion */
.faq-section {
  padding: var(--space-16) 0;
}

.faq-header {
  text-align: center;
  margin-bottom: var(--space-10);
}

.faq-header h2 {
  font-size: var(--font-size-3xl);
  font-weight: 700;
}

.faq-list {
  max-width: 800px;
  margin: 0 auto;
}

.faq-item {
  border-bottom: 1px solid rgba(0,0,0,0.1);
}

.faq-question {
  width: 100%;
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: var(--space-5) 0;
  font-size: var(--font-size-base);
  font-weight: 600;
  text-align: left;
}

.faq-icon {
  transition: transform var(--transition-fast);
}

.faq-item.open .faq-icon {
  transform: rotate(180deg);
}

.faq-answer {
  max-height: 0;
  overflow: hidden;
  transition: max-height var(--transition-base);
}

.faq-item.open .faq-answer {
  max-height: 300px;
}

.faq-answer p {
  padding-bottom: var(--space-5);
  color: #666;
  line-height: 1.7;
}

/* Credits Carousel */
.credits-carousel {
  padding: var(--space-12) 0;
}

.credits-track {
  display: flex;
  gap: var(--space-6);
  overflow-x: auto;
  scroll-behavior: smooth;
  padding: var(--space-2);
  -webkit-overflow-scrolling: touch;
}

.credits-track::-webkit-scrollbar {
  display: none;
}

.credit-card {
  min-width: 300px;
  flex-shrink: 0;
  background: var(--white);
  border-radius: var(--radius-xl);
  padding: var(--space-6);
  box-shadow: var(--shadow-md);
}

/* Certificates Section */
.certificates {
  padding: var(--space-16) 0;
  background: var(--bg-surface);
}

.cert-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: var(--space-6);
}

.cert-card {
  background: var(--white);
  border-radius: var(--radius-xl);
  padding: var(--space-8);
  text-align: center;
  box-shadow: var(--shadow-md);
}

.cert-card-icon {
  width: 80px;
  height: 80px;
  margin: 0 auto var(--space-4);
  background: linear-gradient(135deg, var(--brand-primary) 0%, #FF6B35 100%);
  border-radius: var(--radius-xl);
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--white);
}

.cert-card h3 {
  font-size: var(--font-size-xl);
  font-weight: 700;
  margin-bottom: var(--space-2);
}

.cert-card p {
  font-size: var(--font-size-sm);
  color: #666;
}

/* Mobile Nav */
.mobile-nav-toggle {
  display: none;
  flex-direction: column;
  gap: 5px;
  padding: var(--space-2);
}

.mobile-nav-toggle span {
  width: 24px;
  height: 2px;
  background: var(--foreground);
  border-radius: 2px;
}

@media (max-width: 768px) {
  .pricing-cards {
    grid-template-columns: 1fr;
  }

  .cert-grid {
    grid-template-columns: 1fr;
  }

  .value-props-grid {
    grid-template-columns: 1fr;
  }
}

/* Login Page */
.login-page {
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--bg-surface);
  padding: var(--space-6);
}

.login-container {
  width: 100%;
  max-width: 420px;
}

.login-box {
  background: var(--white);
  border-radius: var(--radius-2xl);
  padding: var(--space-10);
  box-shadow: var(--shadow-xl);
}

.login-header {
  text-align: center;
  margin-bottom: var(--space-8);
}

.login-header h1 {
  font-size: var(--font-size-3xl);
  font-weight: 800;
  margin-bottom: var(--space-2);
}

.login-header p {
  color: #666;
}

.social-login {
  display: flex;
  flex-direction: column;
  gap: var(--space-3);
  margin-bottom: var(--space-6);
}

.social-btn {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: var(--space-3);
  width: 100%;
  padding: var(--space-4);
  border-radius: var(--radius-lg);
  font-size: var(--font-size-sm);
  font-weight: 600;
  transition: all var(--transition-fast);
}

.social-btn-facebook {
  background: #1877F2;
  color: var(--white);
}

.social-btn-apple {
  background: var(--foreground);
  color: var(--white);
}

.social-btn:hover {
  opacity: 0.9;
  transform: translateY(-1px);
}

.divider {
  display: flex;
  align-items: center;
  gap: var(--space-4);
  margin-bottom: var(--space-6);
  color: #999;
  font-size: var(--font-size-sm);
}

.divider::before,
.divider::after {
  content: '';
  flex: 1;
  height: 1px;
  background: rgba(0,0,0,0.1);
}

.form-group {
  margin-bottom: var(--space-5);
}

.form-group label {
  display: block;
  font-size: var(--font-size-sm);
  font-weight: 500;
  margin-bottom: var(--space-2);
}

.form-group input {
  width: 100%;
  padding: var(--space-4);
  border: 1px solid rgba(0,0,0,0.1);
  border-radius: var(--radius-lg);
  font-size: var(--font-size-base);
  transition: border-color var(--transition-fast);
}

.form-group input:focus {
  outline: none;
  border-color: var(--brand-primary);
}

.password-field {
  position: relative;
}

.password-toggle {
  position: absolute;
  right: var(--space-4);
  top: 50%;
  transform: translateY(-50%);
  color: #666;
}

.forgot-link {
  display: block;
  text-align: right;
  font-size: var(--font-size-sm);
  color: var(--brand-primary);
  margin-bottom: var(--space-6);
}

.login-submit {
  width: 100%;
  padding: var(--space-4);
  background: var(--brand-primary);
  color: var(--white);
  font-size: var(--font-size-base);
  font-weight: 700;
  border-radius: var(--radius-lg);
  transition: all var(--transition-fast);
}

.login-submit:hover {
  background: var(--brand-primary-dark);
}

.login-footer {
  text-align: center;
  margin-top: var(--space-6);
  font-size: var(--font-size-sm);
  color: #666;
}

.login-footer a {
  color: var(--brand-primary);
  font-weight: 600;
}

/* Projects Page */
.projects-page {
  background: var(--bg-surface);
  min-height: 100vh;
}

.projects-hero {
  background: var(--foreground);
  color: var(--white);
  padding: var(--space-16) 0;
  text-align: center;
}

.projects-hero h1 {
  font-size: var(--font-size-4xl);
  font-weight: 800;
  margin-bottom: var(--space-4);
}

.projects-hero p {
  font-size: var(--font-size-lg);
  color: rgba(255,255,255,0.7);
}

.projects-filters {
  padding: var(--space-8) 0;
  background: var(--white);
  border-bottom: 1px solid rgba(0,0,0,0.08);
  position: sticky;
  top: 72px;
  z-index: 50;
}

.filter-row {
  display: flex;
  align-items: center;
  gap: var(--space-4);
  flex-wrap: wrap;
}

.filter-group {
  display: flex;
  align-items: center;
  gap: var(--space-2);
}

.filter-label {
  font-size: var(--font-size-sm);
  font-weight: 500;
  color: #666;
}

.filter-select {
  padding: var(--space-2) var(--space-4);
  border: 1px solid rgba(0,0,0,0.1);
  border-radius: var(--radius-full);
  font-size: var(--font-size-sm);
  background: var(--white);
  cursor: pointer;
}

.filter-btn {
  padding: var(--space-2) var(--space-4);
  border-radius: var(--radius-full);
  font-size: var(--font-size-sm);
  font-weight: 500;
  background: var(--bg-muted);
  color: var(--foreground);
  transition: all var(--transition-fast);
}

.filter-btn:hover,
.filter-btn.active {
  background: var(--foreground);
  color: var(--white);
}

.projects-gallery {
  padding: var(--space-12) 0;
}

.masonry-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: var(--space-6);
}

.masonry-item {
  background: var(--white);
  border-radius: var(--radius-xl);
  overflow: hidden;
  box-shadow: var(--shadow-md);
  transition: all var(--transition-base);
}

.masonry-item:hover {
  transform: translateY(-4px);
  box-shadow: var(--shadow-xl);
}

.masonry-item-image {
  aspect-ratio: 1;
  background: var(--bg-muted);
  overflow: hidden;
}

.masonry-item-image img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.masonry-item-content {
  padding: var(--space-4);
}

.masonry-item-title {
  font-size: var(--font-size-base);
  font-weight: 600;
  margin-bottom: var(--space-1);
}

.masonry-item-author {
  font-size: var(--font-size-sm);
  color: #666;
  margin-bottom: var(--space-3);
}

.masonry-item-stats {
  display: flex;
  gap: var(--space-4);
  font-size: var(--font-size-sm);
  color: #666;
}

@media (max-width: 1024px) {
  .masonry-grid {
    grid-template-columns: repeat(3, 1fr);
  }
}

@media (max-width: 768px) {
  .masonry-grid {
    grid-template-columns: repeat(2, 1fr);
  }

  .filter-row {
    flex-direction: column;
    align-items: flex-start;
  }
}

@media (max-width: 480px) {
  .masonry-grid {
    grid-template-columns: 1fr;
  }
}

/* Courses Page */
.courses-page {
  background: var(--bg-surface);
}

.courses-hero {
  background: var(--foreground);
  color: var(--white);
  padding: var(--space-12) 0;
  text-align: center;
}

.courses-hero h1 {
  font-size: var(--font-size-4xl);
  font-weight: 800;
}

.courses-layout {
  display: grid;
  grid-template-columns: 280px 1fr;
  gap: var(--space-8);
  padding: var(--space-8) 0;
}

.sidebar-nav {
  background: var(--white);
  border-radius: var(--radius-xl);
  padding: var(--space-6);
  height: fit-content;
  position: sticky;
  top: 100px;
}

.sidebar-section {
  margin-bottom: var(--space-6);
}

.sidebar-section:last-child {
  margin-bottom: 0;
}

.sidebar-title {
  font-size: var(--font-size-xs);
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  color: #666;
  margin-bottom: var(--space-3);
}

.sidebar-list {
  list-style: none;
}

.sidebar-list li {
  margin-bottom: var(--space-2);
}

.sidebar-list button {
  width: 100%;
  text-align: left;
  padding: var(--space-2) var(--space-3);
  border-radius: var(--radius-md);
  font-size: var(--font-size-sm);
  color: var(--foreground);
  transition: all var(--transition-fast);
}

.sidebar-list button:hover,
.sidebar-list button.active {
  background: var(--brand-primary);
  color: var(--white);
}

.courses-content {
  min-width: 0;
}

.category-section {
  margin-bottom: var(--space-12);
}

.category-title {
  font-size: var(--font-size-2xl);
  font-weight: 700;
  margin-bottom: var(--space-6);
  padding-bottom: var(--space-3);
  border-bottom: 2px solid var(--brand-primary);
}

.course-row {
  display: flex;
  gap: var(--space-4);
  overflow-x: auto;
  padding: var(--space-2);
  -webkit-overflow-scrolling: touch;
}

.course-row::-webkit-scrollbar {
  display: none;
}

.course-row-card {
  min-width: 280px;
  flex-shrink: 0;
}

@media (max-width: 1024px) {
  .courses-layout {
    grid-template-columns: 1fr;
  }

  .sidebar-nav {
    position: static;
  }
}

/* Hero CTA Section */
.hero-cta {
  padding: var(--space-16) 0;
  text-align: center;
  background: linear-gradient(135deg, var(--brand-primary) 0%, #FF6B35 100%);
  color: var(--white);
}

.hero-cta h1 {
  font-size: var(--font-size-5xl);
  font-weight: 800;
  margin-bottom: var(--space-4);
}

.hero-cta p {
  font-size: var(--font-size-xl);
  margin-bottom: var(--space-8);
  opacity: 0.9;
}

.hero-cta-buttons {
  display: flex;
  justify-content: center;
  gap: var(--space-4);
}

.btn-white {
  background: var(--white);
  color: var(--brand-primary);
  padding: var(--space-4) var(--space-8);
  font-size: var(--font-size-lg);
  font-weight: 700;
  border-radius: var(--radius-full);
  transition: all var(--transition-fast);
}

.btn-white:hover {
  transform: translateY(-2px);
  box-shadow: var(--shadow-lg);
}

.btn-outline-white {
  background: transparent;
  color: var(--white);
  padding: var(--space-4) var(--space-8);
  font-size: var(--font-size-lg);
  font-weight: 700;
  border: 2px solid var(--white);
  border-radius: var(--radius-full);
  transition: all var(--transition-fast);
}

.btn-outline-white:hover {
  background: var(--white);
  color: var(--brand-primary);
}

/* Credits Features Section */
.credits-features {
  padding: var(--space-16) 0;
}

.credits-header {
  text-align: center;
  margin-bottom: var(--space-10);
}

.credits-header h2 {
  font-size: var(--font-size-3xl);
  font-weight: 700;
}

/* Pricing Comparison */
.pricing-comparison {
  padding: var(--space-16) 0;
  background: var(--bg-surface);
}

.comparison-table {
  width: 100%;
  max-width: 900px;
  margin: 0 auto;
  background: var(--white);
  border-radius: var(--radius-xl);
  overflow: hidden;
  box-shadow: var(--shadow-lg);
}

.comparison-header {
  display: grid;
  grid-template-columns: 2fr 1fr 1fr;
  background: var(--foreground);
  color: var(--white);
}

.comparison-header > div {
  padding: var(--space-5);
  font-weight: 600;
  text-align: center;
}

.comparison-header > div:first-child {
  text-align: left;
}

.comparison-row {
  display: grid;
  grid-template-columns: 2fr 1fr 1fr;
  border-bottom: 1px solid rgba(0,0,0,0.05);
}

.comparison-row:last-child {
  border-bottom: none;
}

.comparison-row > div {
  padding: var(--space-4) var(--space-5);
  text-align: center;
  display: flex;
  align-items: center;
  justify-content: center;
}

.comparison-row > div:first-child {
  justify-content: flex-start;
}

.check-icon {
  color: #22C55E;
}

.x-icon {
  color: #EF4444;
}

raw_arguments.content:
/* CreativeHub Design System */
@import url('https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800&display=swap');

:root {
  /* Brand Colors */
  --brand-primary: #F02D00;
  --brand-primary-dark: #D02800;
  --brand-primary-light: #FF4D2E;
  --foreground: #171717;
  --white: #FFFFFF;
  --bg-surface: #FAFAFA;
  --bg-elevated: #FFFFFF;
  --bg-muted: #F5F5F5;

  /* OKLCH Conversions for reference */
  /* --brand-primary: oklch(55% 0.22 25); */
  /* --foreground: oklch(10% 0.01 265); */

  /* Typography */
  --font-family: 'Inter', -apple-system, BlinkMacSystemFont, sans-serif;
  --font-size-xs: 0.75rem;
  --font-size-sm: 0.875rem;
  --font-size-base: 1rem;
  --font-size-lg: 1.125rem;
  --font-size-xl: 1.25rem;
  --font-size-2xl: 1.5rem;
  --font-size-3xl: 1.875rem;
  --font-size-4xl: 2.25rem;
  --font-size-5xl: 3rem;
  --font-size-6xl: 3.75rem;

  /* Spacing */
  --space-1: 0.25rem;
  --space-2: 0.5rem;
  --space-3: 0.75rem;
  --space-4: 1rem;
  --space-5: 1.25rem;
  --space-6: 1.5rem;
  --space-8: 2rem;
  --space-10: 2.5rem;
  --space-12: 3rem;
  --space-16: 4rem;
  --space-20: 5rem;
  --space-24: 6rem;

  /* Border Radius */
  --radius-sm: 0.25rem;
  --radius-md: 0.5rem;
  --radius-lg: 0.75rem;
  --radius-xl: 1rem;
  --radius-2xl: 1.5rem;
  --radius-full: 9999px;

  /* Shadows */
  --shadow-sm: 0 1px 2px rgba(0,0,0,0.05);
  --shadow-md: 0 4px 6px -1px rgba(0,0,0,0.1), 0 2px 4px -2px rgba(0,0,0,0.1);
  --shadow-lg: 0 10px 15px -3px rgba(0,0,0,0.1), 0 4px 6px -4px rgba(0,0,0,0.1);
  --shadow-xl: 0 20px 25px -5px rgba(0,0,0,0.1), 0 8px 10px -6px rgba(0,0,0,0.1);

  /* Transitions */
  --transition-fast: 150ms ease;
  --transition-base: 200ms ease;
  --transition-slow: 300ms ease;
}

/* Reset & Base */
*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html {
  font-size: 16px;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

body {
  font-family: var(--font-family);
  font-size: var(--font-size-base);
  line-height: 1.6;
  color: var(--foreground);
  background-color: var(--white);
}

a {
  color: inherit;
  text-decoration: none;
}

button {
  font-family: inherit;
  cursor: pointer;
  border: none;
  background: none;
}

img {
  max-width: 100%;
  height: auto;
  display: block;
}

/* Container */
.container {
  width: 100%;
  max-width: 1280px;
  margin: 0 auto;
  padding: 0 var(--space-6);
}

/* Header */
.header {
  position: sticky;
  top: 0;
  z-index: 100;
  background: var(--white);
  border-bottom: 1px solid rgba(0,0,0,0.08);
}

.header-top {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: var(--space-4) 0;
  gap: var(--space-6);
}

.header-logo {
  font-size: var(--font-size-2xl);
  font-weight: 800;
  color: var(--brand-primary);
  letter-spacing: -0.02em;
}

.header-logo span {
  color: var(--foreground);
}

.header-nav {
  display: flex;
  align-items: center;
  gap: var(--space-8);
}

.header-nav a {
  font-size: var(--font-size-sm);
  font-weight: 500;
  color: var(--foreground);
  transition: color var(--transition-fast);
}

.header-nav a:hover {
  color: var(--brand-primary);
}

.header-actions {
  display: flex;
  align-items: center;
  gap: var(--space-4);
}

.search-box {
  display: flex;
  align-items: center;
  gap: var(--space-2);
  padding: var(--space-2) var(--space-4);
  background: var(--bg-muted);
  border-radius: var(--radius-full);
  min-width: 240px;
}

.search-box input {
  border: none;
  background: transparent;
  outline: none;
  font-size: var(--font-size-sm);
  width: 100%;
}

.search-box svg {
  width: 18px;
  height: 18px;
  color: #666;
}

.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: var(--space-2);
  padding: var(--space-3) var(--space-6);
  font-size: var(--font-size-sm);
  font-weight: 600;
  border-radius: var(--radius-full);
  transition: all var(--transition-fast);
}

.btn-primary {
  background: var(--brand-primary);
  color: var(--white);
}

.btn-primary:hover {
  background: var(--brand-primary-dark);
  transform: translateY(-1px);
}

.btn-secondary {
  background: transparent;
  color: var(--foreground);
  border: 1px solid rgba(0,0,0,0.2);
}

.btn-secondary:hover {
  border-color: var(--foreground);
  background: var(--bg-muted);
}

.btn-ghost {
  background: transparent;
  color: var(--foreground);
}

.btn-ghost:hover {
  background: var(--bg-muted);
}

/* Promotional Banner */
.promo-banner {
  background: linear-gradient(135deg, var(--brand-primary) 0%, #FF6B35 100%);
  color: var(--white);
  padding: var(--space-3) 0;
  position: relative;
}

.promo-content {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: var(--space-8);
  text-align: center;
  font-size: var(--font-size-sm);
  font-weight: 500;
}

.promo-content strong {
  font-weight: 700;
}

.promo-close {
  position: absolute;
  right: var(--space-6);
  top: 50%;
  transform: translateY(-50%);
  background: transparent;
  color: var(--white);
  padding: var(--space-2);
  opacity: 0.8;
}

.promo-close:hover {
  opacity: 1;
}

/* Hero Carousel */
.hero-carousel {
  padding: var(--space-16) 0;
  background: var(--bg-surface);
  overflow: hidden;
}

.carousel-wrapper {
  position: relative;
  max-width: 1280px;
  margin: 0 auto;
}

.carousel-track {
  display: flex;
  transition: transform 0.5s ease;
}

.carousel-slide {
  min-width: 100%;
  display: flex;
  align-items: center;
  gap: var(--space-16);
  padding: 0 var(--space-6);
}

.carousel-slide-content {
  flex: 1;
  max-width: 500px;
}

.carousel-slide-content h2 {
  font-size: var(--font-size-4xl);
  font-weight: 800;
  line-height: 1.1;
  margin-bottom: var(--space-4);
  letter-spacing: -0.02em;
}

.carousel-slide-content p {
  font-size: var(--font-size-lg);
  color: #666;
  margin-bottom: var(--space-6);
}

.carousel-slide-image {
  flex: 1;
  max-width: 600px;
  aspect-ratio: 16/10;
  background: var(--bg-muted);
  border-radius: var(--radius-xl);
  overflow: hidden;
}

.carousel-slide-image img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.specialization-badge {
  display: inline-block;
  padding: var(--space-1) var(--space-3);
  background: var(--brand-primary);
  color: var(--white);
  font-size: var(--font-size-xs);
  font-weight: 700;
  border-radius: var(--radius-sm);
  margin-bottom: var(--space-3);
}

.student-count {
  font-size: var(--font-size-sm);
  color: #666;
  margin-bottom: var(--space-2);
}

.rating {
  display: flex;
  align-items: center;
  gap: var(--space-2);
  margin-bottom: var(--space-4);
}

.rating-stars {
  color: #F4B740;
}

.rating-text {
  font-size: var(--font-size-sm);
  color: #666;
}

.price-info {
  display: flex;
  align-items: baseline;
  gap: var(--space-3);
}

.price-sale {
  font-size: var(--font-size-2xl);
  font-weight: 700;
  color: var(--brand-primary);
}

.price-original {
  font-size: var(--font-size-base);
  color: #999;
  text-decoration: line-through;
}

.discount-badge {
  background: #FFEBEB;
  color: var(--brand-primary);
  font-size: var(--font-size-xs);
  font-weight: 700;
  padding: var(--space-1) var(--space-2);
  border-radius: var(--radius-sm);
}

.carousel-nav {
  display: flex;
  justify-content: center;
  align-items: center;
  gap: var(--space-4);
  margin-top: var(--space-8);
}

.carousel-nav button {
  width: 48px;
  height: 48px;
  border-radius: var(--radius-full);
  background: var(--white);
  box-shadow: var(--shadow-md);
  display: flex;
  align-items: center;
  justify-content: center;
  transition: all var(--transition-fast);
}

.carousel-nav button:hover {
  background: var(--bg-muted);
  transform: scale(1.05);
}

.carousel-nav button:disabled {
  opacity: 0.5;
  cursor: not-allowed;
}

.carousel-pagination {
  display: flex;
  gap: var(--space-2);
}

.carousel-dot {
  width: 10px;
  height: 10px;
  border-radius: var(--radius-full);
  background: rgba(0,0,0,0.2);
  transition: all var(--transition-fast);
}

.carousel-dot.active {
  width: 32px;
  background: var(--brand-primary);
}

/* Course Cards */
.course-grid {
  padding: var(--space-16) 0;
}

.section-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: var(--space-8);
}

.section-title {
  font-size: var(--font-size-3xl);
  font-weight: 700;
  letter-spacing: -0.02em;
}

.course-cards {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(280px, 1fr));
  gap: var(--space-6);
}

.course-card {
  background: var(--white);
  border-radius: var(--radius-xl);
  overflow: hidden;
  box-shadow: var(--shadow-md);
  transition: all var(--transition-base);
  cursor: pointer;
}

.course-card:hover {
  transform: translateY(-4px);
  box-shadow: var(--shadow-xl);
}

.course-card-image {
  aspect-ratio: 16/10;
  background: var(--bg-muted);
  overflow: hidden;
}

.course-card-image img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  transition: transform var(--transition-slow);
}

.course-card:hover .course-card-image img {
  transform: scale(1.05);
}

.course-card-content {
  padding: var(--space-5);
}

.course-card-badges {
  display: flex;
  gap: var(--space-2);
  margin-bottom: var(--space-3);
}

.badge {
  font-size: var(--font-size-xs);
  font-weight: 600;
  padding: var(--space-1) var(--space-2);
  border-radius: var(--radius-sm);
}

.badge-bestseller {
  background: #FEF3C7;
  color: #92400E;
}

.badge-free {
  background: #D1FAE5;
  color: #065F46;
}

.course-card-title {
  font-size: var(--font-size-base);
  font-weight: 600;
  margin-bottom: var(--space-2);
  line-height: 1.4;
}

.course-card-instructor {
  font-size: var(--font-size-sm);
  color: #666;
  margin-bottom: var(--space-3);
}

.course-card-stats {
  display: flex;
  align-items: center;
  gap: var(--space-4);
  font-size: var(--font-size-sm);
  color: #666;
  margin-bottom: var(--space-3);
}

.stat-item {
  display: flex;
  align-items: center;
  gap: var(--space-1);
}

.course-card-price {
  display: flex;
  align-items: baseline;
  gap: var(--space-2);
}

.price-current {
  font-size: var(--font-size-xl);
  font-weight: 700;
}

.price-was {
  font-size: var(--font-size-sm);
  color: #999;
  text-decoration: line-through;
}

/* Course Carousel (Horizontal Scroll) */
.course-carousel {
  padding: var(--space-12) 0;
  background: var(--bg-surface);
  overflow: hidden;
}

.course-carousel-track {
  display: flex;
  gap: var(--space-6);
  overflow-x: auto;
  scroll-behavior: smooth;
  padding: var(--space-2);
  -webkit-overflow-scrolling: touch;
}

.course-carousel-track::-webkit-scrollbar {
  display: none;
}

.course-carousel-card {
  min-width: 300px;
  flex-shrink: 0;
}

/* Value Props Section */
.value-props {
  padding: var(--space-20) 0;
}

.value-props-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
  gap: var(--space-8);
}

.value-prop-card {
  text-align: center;
  padding: var(--space-8);
}

.value-prop-icon {
  width: 64px;
  height: 64px;
  margin: 0 auto var(--space-4);
  background: linear-gradient(135deg, var(--brand-primary) 0%, #FF6B35 100%);
  border-radius: var(--radius-xl);
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--white);
}

.value-prop-title {
  font-size: var(--font-size-lg);
  font-weight: 600;
  margin-bottom: var(--space-2);
}

.value-prop-desc {
  font-size: var(--font-size-sm);
  color: #666;
  line-height: 1.6;
}

/* Footer */
.footer {
  background: var(--foreground);
  color: var(--white);
  padding: var(--space-16) 0 var(--space-8);
}

.footer-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: var(--space-12);
  margin-bottom: var(--space-12);
}

.footer-section h4 {
  font-size: var(--font-size-sm);
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  margin-bottom: var(--space-4);
  color: rgba(255,255,255,0.5);
}

.footer-section ul {
  list-style: none;
}

.footer-section li {
  margin-bottom: var(--space-2);
}

.footer-section a {
  font-size: var(--font-size-sm);
  color: rgba(255,255,255,0.8);
  transition: color var(--transition-fast);
}

.footer-section a:hover {
  color: var(--white);
}

.footer-bottom {
  padding-top: var(--space-8);
  border-top: 1px solid rgba(255,255,255,0.1);
  display: flex;
  justify-content: space-between;
  align-items: center;
}

.footer-bottom p {
  font-size: var(--font-size-sm);
  color: rgba(255,255,255,0.5);
}

.footer-legal {
  display: flex;
  gap: var(--space-6);
}

.footer-legal a {
  font-size: var(--font-size-sm);
  color: rgba(255,255,255,0.5);
  transition: color var(--transition-fast);
}

.footer-legal a:hover {
  color: var(--white);
}

/* Footer Accordion (Mobile) */
.footer-accordion {
  display: none;
}

.footer-accordion-item {
  border-bottom: 1px solid rgba(255,255,255,0.1);
}

.footer-accordion-header {
  width: 100%;
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: var(--space-4) 0;
  color: var(--white);
  font-weight: 600;
  text-align: left;
}

.footer-accordion-icon {
  transition: transform var(--transition-fast);
}

.footer-accordion-item.open .footer-accordion-icon {
  transform: rotate(180deg);
}

.footer-accordion-content {
  max-height: 0;
  overflow: hidden;
  transition: max-height var(--transition-base);
}

.footer-accordion-item.open .footer-accordion-content {
  max-height: 500px;
}

.footer-accordion-content ul {
  padding-bottom: var(--space-4);
}

/* Responsive */
@media (max-width: 1024px) {
  .header-nav {
    display: none;
  }

  .mobile-nav-toggle {
    display: flex;
  }

  .search-box {
    min-width: 180px;
  }

  .carousel-slide {
    flex-direction: column;
    text-align: center;
    gap: var(--space-8);
  }

  .carousel-slide-content {
    max-width: 100%;
  }

  .carousel-slide-image {
    max-width: 100%;
  }

  .footer-grid {
    grid-template-columns: repeat(2, 1fr);
  }
}

@media (max-width: 768px) {
  .promo-content {
    flex-direction: column;
    gap: var(--space-2);
  }

  .section-header {
    flex-direction: column;
    align-items: flex-start;
    gap: var(--space-4);
  }

  .course-cards {
    grid-template-columns: 1fr;
  }

  .footer-grid {
    display: none;
  }

  .footer-accordion {
    display: block;
  }

  .footer-bottom {
    flex-direction: column;
    gap: var(--space-4);
    text-align: center;
  }

  .footer-legal {
    flex-wrap: wrap;
    justify-content: center;
  }
}

/* Plus Page Styles */
.pricing-section {
  padding: var(--space-16) 0;
  background: var(--bg-surface);
}

.pricing-header {
  text-align: center;
  margin-bottom: var(--space-12);
}

.pricing-header h2 {
  font-size: var(--font-size-4xl);
  font-weight: 800;
  margin-bottom: var(--space-4);
}

.pricing-header p {
  font-size: var(--font-size-lg);
  color: #666;
}

.pricing-toggle {
  display: flex;
  justify-content: center;
  align-items: center;
  gap: var(--space-4);
  margin-bottom: var(--space-10);
}

.toggle-label {
  font-size: var(--font-size-sm);
  font-weight: 500;
  color: #666;
}

.toggle-label.active {
  color: var(--foreground);
  font-weight: 700;
}

.toggle-switch {
  position: relative;
  width: 56px;
  height: 30px;
  background: #ddd;
  border-radius: var(--radius-full);
  cursor: pointer;
  transition: background var(--transition-fast);
}

.toggle-switch.active {
  background: var(--brand-primary);
}

.toggle-switch::after {
  content: '';
  position: absolute;
  top: 3px;
  left: 3px;
  width: 24px;
  height: 24px;
  background: var(--white);
  border-radius: var(--radius-full);
  transition: transform var(--transition-fast);
}

.toggle-switch.active::after {
  transform: translateX(26px);
}

.pricing-cards {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: var(--space-6);
  max-width: 800px;
  margin: 0 auto;
}

.pricing-card {
  background: var(--white);
  border-radius: var(--radius-xl);
  padding: var(--space-8);
  box-shadow: var(--shadow-lg);
  position: relative;
}

.pricing-card.featured {
  border: 2px solid var(--brand-primary);
}

.pricing-card.featured::before {
  content: 'Best Value';
  position: absolute;
  top: -12px;
  left: 50%;
  transform: translateX(-50%);
  background: var(--brand-primary);
  color: var(--white);
  padding: var(--space-1) var(--space-4);
  border-radius: var(--radius-full);
  font-size: var(--font-size-xs);
  font-weight: 700;
}

.plan-name {
  font-size: var(--font-size-lg);
  font-weight: 600;
  margin-bottom: var(--space-4);
}

.plan-price {
  margin-bottom: var(--space-4);
}

.plan-price .amount {
  font-size: var(--font-size-4xl);
  font-weight: 800;
}

.plan-price .period {
  font-size: var(--font-size-base);
  color: #666;
}

.plan-billed {
  font-size: var(--font-size-sm);
  color: #666;
  margin-bottom: var(--space-4);
}

.plan-savings {
  display: inline-block;
  background: #D1FAE5;
  color: #065F46;
  padding: var(--space-1) var(--space-3);
  border-radius: var(--radius-full);
  font-size: var(--font-size-xs);
  font-weight: 700;
  margin-bottom: var(--space-6);
}

.plan-features {
  list-style: none;
  margin-bottom: var(--space-6);
}

.plan-features li {
  display: flex;
  align-items: center;
  gap: var(--space-3);
  font-size: var(--font-size-sm);
  margin-bottom: var(--space-3);
}

.plan-features li svg {
  width: 18px;
  height: 18px;
  color: var(--brand-primary);
  flex-shrink: 0;
}

/* FAQ Accordion */
.faq-section {
  padding: var(--space-16) 0;
}

.faq-header {
  text-align: center;
  margin-bottom: var(--space-10);
}

.faq-header h2 {
  font-size: var(--font-size-3xl);
  font-weight: 700;
}

.faq-list {
  max-width: 800px;
  margin: 0 auto;
}

.faq-item {
  border-bottom: 1px solid rgba(0,0,0,0.1);
}

.faq-question {
  width: 100%;
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: var(--space-5) 0;
  font-size: var(--font-size-base);
  font-weight: 600;
  text-align: left;
}

.faq-icon {
  transition: transform var(--transition-fast);
}

.faq-item.open .faq-icon {
  transform: rotate(180deg);
}

.faq-answer {
  max-height: 0;
  overflow: hidden;
  transition: max-height var(--transition-base);
}

.faq-item.open .faq-answer {
  max-height: 300px;
}

.faq-answer p {
  padding-bottom: var(--space-5);
  color: #666;
  line-height: 1.7;
}

/* Credits Carousel */
.credits-carousel {
  padding: var(--space-12) 0;
}

.credits-track {
  display: flex;
  gap: var(--space-6);
  overflow-x: auto;
  scroll-behavior: smooth;
  padding: var(--space-2);
  -webkit-overflow-scrolling: touch;
}

.credits-track::-webkit-scrollbar {
  display: none;
}

.credit-card {
  min-width: 300px;
  flex-shrink: 0;
  background: var(--white);
  border-radius: var(--radius-xl);
  padding: var(--space-6);
  box-shadow: var(--shadow-md);
}

/* Certificates Section */
.certificates {
  padding: var(--space-16) 0;
  background: var(--bg-surface);
}

.cert-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: var(--space-6);
}

.cert-card {
  background: var(--white);
  border-radius: var(--radius-xl);
  padding: var(--space-8);
  text-align: center;
  box-shadow: var(--shadow-md);
}

.cert-card-icon {
  width: 80px;
  height: 80px;
  margin: 0 auto var(--space-4);
  background: linear-gradient(135deg, var(--brand-primary) 0%, #FF6B35 100%);
  border-radius: var(--radius-xl);
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--white);
}

.cert-card h3 {
  font-size: var(--font-size-xl);
  font-weight: 700;
  margin-bottom: var(--space-2);
}

.cert-card p {
  font-size: var(--font-size-sm);
  color: #666;
}

/* Mobile Nav */
.mobile-nav-toggle {
  display: none;
  flex-direction: column;
  gap: 5px;
  padding: var(--space-2);
}

.mobile-nav-toggle span {
  width: 24px;
  height: 2px;
  background: var(--foreground);
  border-radius: 2px;
}

@media (max-width: 768px) {
  .pricing-cards {
    grid-template-columns: 1fr;
  }

  .cert-grid {
    grid-template-columns: 1fr;
  }

  .value-props-grid {
    grid-template-columns: 1fr;
  }
}

/* Login Page */
.login-page {
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--bg-surface);
  padding: var(--space-6);
}

.login-container {
  width: 100%;
  max-width: 420px;
}

.login-box {
  background: var(--white);
  border-radius: var(--radius-2xl);
  padding: var(--space-10);
  box-shadow: var(--shadow-xl);
}

.login-header {
  text-align: center;
  margin-bottom: var(--space-8);
}

.login-header h1 {
  font-size: var(--font-size-3xl);
  font-weight: 800;
  margin-bottom: var(--space-2);
}

.login-header p {
  color: #666;
}

.social-login {
  display: flex;
  flex-direction: column;
  gap: var(--space-3);
  margin-bottom: var(--space-6);
}

.social-btn {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: var(--space-3);
  width: 100%;
  padding: var(--space-4);
  border-radius: var(--radius-lg);
  font-size: var(--font-size-sm);
  font-weight: 600;
  transition: all var(--transition-fast);
}

.social-btn-facebook {
  background: #1877F2;
  color: var(--white);
}

.social-btn-apple {
  background: var(--foreground);
  color: var(--white);
}

.social-btn:hover {
  opacity: 0.9;
  transform: translateY(-1px);
}

.divider {
  display: flex;
  align-items: center;
  gap: var(--space-4);
  margin-bottom: var(--space-6);
  color: #999;
  font-size: var(--font-size-sm);
}

.divider::before,
.divider::after {
  content: '';
  flex: 1;
  height: 1px;
  background: rgba(0,0,0,0.1);
}

.form-group {
  margin-bottom: var(--space-5);
}

.form-group label {
  display: block;
  font-size: var(--font-size-sm);
  font-weight: 500;
  margin-bottom: var(--space-2);
}

.form-group input {
  width: 100%;
  padding: var(--space-4);
  border: 1px solid rgba(0,0,0,0.1);
  border-radius: var(--radius-lg);
  font-size: var(--font-size-base);
  transition: border-color var(--transition-fast);
}

.form-group input:focus {
  outline: none;
  border-color: var(--brand-primary);
}

.password-field {
  position: relative;
}

.password-toggle {
  position: absolute;
  right: var(--space-4);
  top: 50%;
  transform: translateY(-50%);
  color: #666;
}

.forgot-link {
  display: block;
  text-align: right;
  font-size: var(--font-size-sm);
  color: var(--brand-primary);
  margin-bottom: var(--space-6);
}

.login-submit {
  width: 100%;
  padding: var(--space-4);
  background: var(--brand-primary);
  color: var(--white);
  font-size: var(--font-size-base);
  font-weight: 700;
  border-radius: var(--radius-lg);
  transition: all var(--transition-fast);
}

.login-submit:hover {
  background: var(--brand-primary-dark);
}

.login-footer {
  text-align: center;
  margin-top: var(--space-6);
  font-size: var(--font-size-sm);
  color: #666;
}

.login-footer a {
  color: var(--brand-primary);
  font-weight: 600;
}

/* Projects Page */
.projects-page {
  background: var(--bg-surface);
  min-height: 100vh;
}

.projects-hero {
  background: var(--foreground);
  color: var(--white);
  padding: var(--space-16) 0;
  text-align: center;
}

.projects-hero h1 {
  font-size: var(--font-size-4xl);
  font-weight: 800;
  margin-bottom: var(--space-4);
}

.projects-hero p {
  font-size: var(--font-size-lg);
  color: rgba(255,255,255,0.7);
}

.projects-filters {
  padding: var(--space-8) 0;
  background: var(--white);
  border-bottom: 1px solid rgba(0,0,0,0.08);
  position: sticky;
  top: 72px;
  z-index: 50;
}

.filter-row {
  display: flex;
  align-items: center;
  gap: var(--space-4);
  flex-wrap: wrap;
}

.filter-group {
  display: flex;
  align-items: center;
  gap: var(--space-2);
}

.filter-label {
  font-size: var(--font-size-sm);
  font-weight: 500;
  color: #666;
}

.filter-select {
  padding: var(--space-2) var(--space-4);
  border: 1px solid rgba(0,0,0,0.1);
  border-radius: var(--radius-full);
  font-size: var(--font-size-sm);
  background: var(--white);
  cursor: pointer;
}

.filter-btn {
  padding: var(--space-2) var(--space-4);
  border-radius: var(--radius-full);
  font-size: var(--font-size-sm);
  font-weight: 500;
  background: var(--bg-muted);
  color: var(--foreground);
  transition: all var(--transition-fast);
}

.filter-btn:hover,
.filter-btn.active {
  background: var(--foreground);
  color: var(--white);
}

.projects-gallery {
  padding: var(--space-12) 0;
}

.masonry-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: var(--space-6);
}

.masonry-item {
  background: var(--white);
  border-radius: var(--radius-xl);
  overflow: hidden;
  box-shadow: var(--shadow-md);
  transition: all var(--transition-base);
}

.masonry-item:hover {
  transform: translateY(-4px);
  box-shadow: var(--shadow-xl);
}

.masonry-item-image {
  aspect-ratio: 1;
  background: var(--bg-muted);
  overflow: hidden;
}

.masonry-item-image img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.masonry-item-content {
  padding: var(--space-4);
}

.masonry-item-title {
  font-size: var(--font-size-base);
  font-weight: 600;
  margin-bottom: var(--space-1);
}

.masonry-item-author {
  font-size: var(--font-size-sm);
  color: #666;
  margin-bottom: var(--space-3);
}

.masonry-item-stats {
  display: flex;
  gap: var(--space-4);
  font-size: var(--font-size-sm);
  color: #666;
}

@media (max-width: 1024px) {
  .masonry-grid {
    grid-template-columns: repeat(3, 1fr);
  }
}

@media (max-width: 768px) {
  .masonry-grid {
    grid-template-columns: repeat(2, 1fr);
  }

  .filter-row {
    flex-direction: column;
    align-items: flex-start;
  }
}

@media (max-width: 480px) {
  .masonry-grid {
    grid-template-columns: 1fr;
  }
}

/* Courses Page */
.courses-page {
  background: var(--bg-surface);
}

.courses-hero {
  background: var(--foreground);
  color: var(--white);
  padding: var(--space-12) 0;
  text-align: center;
}

.courses-hero h1 {
  font-size: var(--font-size-4xl);
  font-weight: 800;
}

.courses-layout {
  display: grid;
  grid-template-columns: 280px 1fr;
  gap: var(--space-8);
